def flag_historical_refunds(apps, schema_editor):
    Payment = apps.get_model("payments", "Payment")
    ReturnRequest = apps.get_model("complaints", "ReturnRequest")
    database = schema_editor.connection.alias
    historical_orders = ReturnRequest.objects.using(database).filter(
        status__in=["REFUNDED", "CLOSED"],
    ).values_list("order_item__order_id", flat=True)
    Payment.objects.using(database).filter(
        models.Q(status__in=["REFUNDED", "PARTIALLY_REFUNDED"])
        | models.Q(order_id__in=historical_orders)
    ).update(refund_review_required=True)


